void _swap(List<int> list, int a, int b) {
  final temp = list[a];
  list[a] = list[b];
  list[b] = temp;
}

void _siftDown(List<int> list, int parent, int limit) {
  while (true) {
    final leftChild = 2 * parent + 1;
    final rightChild = 2 * parent + 2;

    int largest = parent;
    if (leftChild < limit && list[leftChild] > list[largest]) {
      largest = leftChild;
    }
    if (rightChild < limit && list[rightChild] > list[largest]) {
      largest = rightChild;
    }
    if (largest == parent) break;
    _swap(list, parent, largest);
    parent = largest;
  }
}
