  List<List<double>> dp = List.generate(rows, (_) => List.filled(cols, 0.0));

  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      var currentVal = grid[r][c];

      if (r > 0) {
        double valFromUp = dp[r - 1][c] + currentVal;
        if (valFromUp > dp[r][c]) {
          dp[r][c] = valFromUp;
        }
      }

      if (c > 0) {
        double valFromLeft = dp[r][c - 1] + currentVal;
        if (valFromLeft > dp[r][c]) {
          dp[r][c] = valFromLeft;
        }
      }

      if (currentVal > 0 && r > 0 && c > 0) {
        double diagonalValue = dp[r - 1][c - 1] + currentVal;
        if (diagonalValue > dp[r][c]) {
          dp[r][c] = diagonalValue;
        }
      }
    }
  }

  // Calculate the maximum value in the last row and column
  double maxValue = 0.0;
  for (var i = 0; i < rows; i++) {
    maxValue = max(maxValue, dp[i][cols - 1]);
  }
  for (var j = 0; j < cols; j++) {
    maxValue = max(maxValue, dp[rows - 1][j]);
  }

  // Convert to integer since we're dealing with fill amounts
  return maxValue.floor();
