String solve(String s) {
  var n = s.length;
  if (n == 0) return '';

  int i = 0, j = n - 1;
  while (i < j) {
    while (s[i] != ' ') i++;
    while (s[j] != ' ') j--;
    if (i >= j) break;

    // Swap characters at positions i and j
    var c = s[i];
    s = s.substring(0, i) + s[j] + s.substring(i+1, j) + c + s.substring(j+1);
    i++;
    j--;
  }

  return s;
}

